{"sql":"WITH m AS (
  SELECT month, order_date FROM order_lines WHERE line_type = '销售' AND month LIKE '2011-%'
)
SELECT month, count(DISTINCT order_date) AS trading_days, min(order_date) AS first_day, max(order_date) AS last_day
FROM m GROUP BY month ORDER BY month","purpose":"确认每月实际有销售的日期数与起止日（尤其 2011-01 与 2011-12 是否完整）"}
